/**
 * 직원 목록을 표와 파일로 내보내는 규칙.
 *
 * 같은 직원을 표의 칸과 CSV 의 열이 각자 문장으로 만들면(예: 표는 삼항으로
 * "재직", 내보내기는 다른 표) 같은 데이터가 화면과 파일에서 다르게 읽힌다 —
 * 이 저장소에서 반복된 어긋남이다. 그래서 라벨과 행 만들기를 여기 한 곳에 두고
 * `EmployeesPage` 의 표와 CSV 가 모두 이것을 쓴다. `seatMapLink.ts`·
 * `silentSso.ts` 가 같은 꼴의 짝이다.
 *
 * 열 이름은 마음대로 짓지 않는다. 같은 화면의 직원 양식
 * (`EmployeesPage.downloadTemplate`)과 서버 파서(`internal/app/employees.go:159`
 * 의 `find`)가 쓰는 말을 그대로 써서, 같은 값이 화면·양식·파일에서 같은 이름으로
 * 읽히게 한다. 그래서 직급은 title, 직책은 position 이고 조직 열은 표의
 * 머리글("조직")이 아니라 "조직명"이다.
 *
 * 다만 이 파일 자체는 가져오기 입력이 아니다. 조직을 가리키는 "조직코드"
 * (organizations.external_id)가 없어 그대로 올리면 `saveEmployee`
 * (`findOrganization`)가 조직을 "조직명"으로만 찾는다 — organizations.name 에는
 * UNIQUE 가 없어(migrations.sql:14-22) 같은 이름의 조직이 여럿이면 그 행이
 * 걸리고, 조직명 칸이 빈 행은 소속을 지운다. "좌석" 열은 파서가 읽지 않으므로
 * 좌석도 반영되지 않는다. 조직을 바꿀 때는 조직코드가 있는 직원 양식을 쓰고
 * 좌석은 좌석 일괄 배정을 쓴다. USER_GUIDE 3.4 절이 그렇게 안내한다.
 */

import type { Employee } from "../types";

/** 재직상태 코드 → 화면 라벨. 서버가 employees.status 에 넣는 값이 키다. */
const STATUS_LABELS: Record<string, string> = {
  active: "재직",
  leave: "휴직",
  retired: "퇴직",
};

/**
 * 재직상태 한 칸. 표와 CSV 가 같은 값을 보게 하는 유일한 출처다.
 *
 * 모르는 값은 "퇴직"이다 — 표가 active/leave 가 아닌 값을 모두 그렇게 보여
 * 왔기 때문이고, 여기서 갈래를 바꾸면 같은 직원이 화면에서 다르게 읽힌다.
 */
export const employeeStatusLabel = (status: string) =>
  STATUS_LABELS[status] ?? "퇴직";

/** 좌석 한 칸. 좌석이 없는 것은 빈 칸이 아니라 "미배정"이라고 적는다. */
export const employeeSeatLabel = (seatNo?: string) => seatNo || "미배정";

/** 파일의 머리글. "좌석"은 파서가 모르는 열이지만 배정 현황을 눈으로 보려고 넣는다. */
export const EMPLOYEE_CSV_HEADERS = [
  "이름",
  "사번",
  "이메일",
  "조직명",
  "직급",
  "직책",
  "근무지",
  "좌석",
  "재직상태",
];

/**
 * 화면에 보이는 목록을 그대로 CSV 행으로 옮긴다. 다시 조회하지 않으므로 표의
 * 행 수와 파일의 데이터 행 수가 같다.
 *
 * 빈 값은 빈 칸으로 둔다. 표가 보여주는 자리 표시 "-" 를 넣으면 `csvCell` 이
 * 수식으로 시작하는 값으로 보고 "'-" 로 바꿔 스프레드시트에 그대로 남는다.
 */
export const employeeCsvRows = (items: Employee[]): string[][] =>
  items.map((employee) => [
    employee.name,
    employee.employeeNo,
    employee.email ?? "",
    employee.organizationName ?? "",
    employee.title ?? "",
    employee.position ?? "",
    employee.workplace ?? "",
    employeeSeatLabel(employee.seatNo),
    employeeStatusLabel(employee.status),
  ]);
/**
 * 좌석맵 화면과 주소(쿼리)를 잇는 규칙.
 *
 * 좌석맵은 `?map=`·`?q=`·`?edit=1` 로 들어오는 깊은 링크를 읽고, 검색·도면
 * 선택을 다시 주소에 적는다. 읽는 쪽과 쓰는 쪽이 각자 `searchParams.get(...)`
 * 을 부르면 한쪽만 다듬어(예: 공백) 같은 주소를 다르게 읽는 일이 생긴다 — 이
 * 저장소에서 반복된 어긋남이다. 그래서 규칙을 여기 한 곳에 두고 양쪽이 쓴다.
 * `silentSso.ts` 의 `loginPathFor`/`returnToFrom` 이 같은 꼴의 짝이다.
 */

export interface SeatMapParams {
  /** 볼 도면(floor map) id. 없으면 빈 문자열. */
  mapId: string;
  /** 검색어. 앞뒤 공백을 떼고, 공백만 있으면 없는 것으로 친다. */
  query: string;
  /** 편집 모드로 열라는 표시. 읽기만 하고 화면에서 다시 쓰지는 않는다. */
  edit: boolean;
}

/** 주소에서 좌석맵이 보는 값만 추린다. */
export function readSeatMapParams(params: URLSearchParams): SeatMapParams {
  return {
    mapId: params.get("map")?.trim() ?? "",
    query: params.get("q")?.trim() ?? "",
    edit: params.get("edit") === "1",
  };
}

/**
 * 주어진 값만 갈아 끼운 새 쿼리.
 *
 * 준 키만 손대고 나머지(`edit`·아직 없는 미래의 키)는 그대로 둔다. 값이 비면
 * 키를 지워 `?q=` 같은 빈 껍데기를 주소에 남기지 않는다.
 */
export function writeSeatMapParams(
  prev: URLSearchParams,
  next: { mapId?: string; query?: string },
): URLSearchParams {
  const params = new URLSearchParams(prev);
  const put = (key: string, value: string | undefined) => {
    if (value === undefined) return;
    const trimmed = value.trim();
    if (trimmed) params.set(key, trimmed);
    else params.delete(key);
  };
  put("map", next.mapId);
  put("q", next.query);
  return params;
}

/**
 * "이 검색은 이미 했다"를 가리키는 키.
 *
 * 검색 제출이 주소에 `q` 를 쓰면 `q` 를 감시하는 effect 가 다시 깨어나 같은
 * 검색을 한 번 더 보낸다. 제출 경로가 이 키를 먼저 세워 두면 effect 는 조용히
 * 지나간다 — 그러려면 두 경로가 같은 입력에서 반드시 같은 키를 내야 한다.
 */
export function seatSearchKey(mapId: string, query: string): string {
  return `${mapId}:${query.trim()}`;
}
/**
 * 직원 목록 조회 쿼리를 짓는 규칙.
 *
 * 화면의 필터(검색어·재직상태·배정상태·조직)는 여러 자리에서 조회를 부른다 —
 * 첫 로드, 검색 제출, Select 세 개, 가져오기 뒤 새로고침. 그 자리마다
 * `new URLSearchParams` 을 손으로 조립하면 한쪽만 키 이름을 틀리거나 빈 값을
 * `?status=` 로 흘려 서버가 다르게 읽는다 — 이 저장소에서 반복된 어긋남이다.
 * 그래서 키 이름과 빈 값 규칙을 여기 한 곳에 두고 부르는 쪽이 모두 이것을 쓴다.
 * `seatMapLink.ts`·`silentSso.ts`·`employeeExport.ts` 가 같은 꼴의 짝이다.
 *
 * 키 이름은 마음대로 짓지 않는다. 서버 `listEmployees`
 * (`internal/app/employees.go:59-63`)가 읽는 `q`·`organizationId`·`status`·
 * `assignment` 를 그대로 쓴다.
 */

/**
 * 한 번에 받아 오는 최대 인원.
 *
 * 서버는 `limit` 을 500 까지만 받고(`employees.go:65-67`) 전체 건수는 돌려주지
 * 않는다. 그래서 화면은 언제나 상한으로 받고 "최대 500명 표시" 를 안내한다 —
 * 조건에 상관없이 같은 값이어야 표에 보이는 것과 CSV 가 어긋나지 않는다.
 */
export const EMPLOYEE_QUERY_LIMIT = "500";

export interface EmployeeFilters {
  /** 이름·사번·이메일·조직명을 함께 훑는 자유 검색어. */
  q?: string;
  /** 재직상태 코드(active|leave|retired). 빈 값은 전체. */
  status?: string;
  /** 배정상태(assigned|unassigned). 빈 값은 전체. */
  assignment?: string;
  /** 조직 id. 빈 값은 전체 조직. 조직명이 아니라 id 다. */
  organizationId?: string;
}

const filterKeys = ["q", "organizationId", "status", "assignment"] as const;

function normalize(filters: EmployeeFilters): Required<EmployeeFilters> {
  const status = filters.status?.trim() ?? "";
  const assignment = filters.assignment?.trim() ?? "";
  return {
    q: filters.q?.trim() ?? "",
    organizationId: filters.organizationId?.trim() ?? "",
    status: ["active", "leave", "retired"].includes(status) ? status : "",
    assignment: ["assigned", "unassigned"].includes(assignment)
      ? assignment
      : "",
  };
}

/** 주소의 네 필터를 읽는다. 모르는 enum은 전체로 취급한다. */
export function readEmployeeParams(
  params: URLSearchParams,
): Required<EmployeeFilters> {
  return normalize(
    Object.fromEntries(filterKeys.map((key) => [key, params.get(key) ?? ""])),
  );
}

/** 원본과 모르는 키를 보존한다. undefined는 유지, 빈 값은 해당 키 삭제. */
export function writeEmployeeParams(
  params: URLSearchParams,
  filters: EmployeeFilters,
): URLSearchParams {
  const next = new URLSearchParams(params);
  const normalized = normalize(filters);
  for (const key of filterKeys) {
    if (filters[key] === undefined) continue;
    if (normalized[key]) next.set(key, normalized[key]);
    else next.delete(key);
  }
  return next;
}

/** API는 같은 정규화 규칙을 쓰되 주소의 limit이나 모르는 키를 받지 않는다. */
export function employeeQuery(filters: EmployeeFilters): URLSearchParams {
  return writeEmployeeParams(
    new URLSearchParams({ limit: EMPLOYEE_QUERY_LIMIT }),
    filters,
  );
}
