// "행을 읽다 깨지는" 경우를 만들 수 있는 유일한 수단이다.
type fakeRows struct {
	values  [][]any
	idx     int
	scanErr error // Scan 이 돌려줄 오류 (행을 읽다 연결이 끊긴 경우)
	err     error // 루프가 끝난 뒤 Err() 가 돌려줄 오류 (조회가 중간에 끊긴 경우)
	scans   int
}

func (f *fakeRows) Next() bool {
	if f.idx >= len(f.values) {
		return false
	}
	f.idx++
	return true
}

func (f *fakeRows) Err() error { return f.err }

func (f *fakeRows) Scan(dest ...any) error {
	f.scans++
	if f.scanErr != nil {
		return f.scanErr
	}
	row := f.values[f.idx-1]
	if len(row) != len(dest) {
		return fmt.Errorf("fakeRows: 행의 값이 %d개인데 dest 는 %d개다", len(row), len(dest))
	}
	for i, v := range row {
		switch target := dest[i].(type) {
		case *string:
			s, ok := v.(string)
			if !ok {
				return fmt.Errorf("fakeRows: dest[%d] 는 string 인데 값은 %T 다", i, v)
			}
			*target = s
		case **string:
			if v == nil {
				*target = nil
				continue
			}
			p, ok := v.(*string)
			if !ok {
				return fmt.Errorf("fakeRows: dest[%d] 는 *string 인데 값은 %T 다", i, v)
			}
			*target = p
		case *float64:
			f, ok := v.(float64)
			if !ok {
				return fmt.Errorf("fakeRows: dest[%d] 는 float64 인데 값은 %T 다", i, v)
			}
			*target = f
		case **float64:
			if v == nil {
				*target = nil
				continue
			}
			p, ok := v.(*float64)
			if !ok {
				return fmt.Errorf("fakeRows: dest[%d] 는 *float64 인데 값은 %T 다", i, v)
			}

func (s *Server) listEmployees(w http.ResponseWriter, r *http.Request) {
	q := strings.TrimSpace(r.URL.Query().Get("q"))
	org := r.URL.Query().Get("organizationId")
	status := r.URL.Query().Get("status")
	assignment := r.URL.Query().Get("assignment")
	limit := 100
	if v, _ := strconv.Atoi(r.URL.Query().Get("limit")); v > 0 && v <= 500 {
		limit = v
	}
	rows, err := s.db.Query(r.Context(), `SELECT e.id,e.employee_no,e.name,COALESCE(e.email,''),e.organization_id,COALESCE(o.name,''),COALESCE(e.title,''),COALESCE(e.position,''),COALESCE(e.workplace,''),e.status,a.seat_id,COALESCE(se.seat_no,'') FROM employees e LEFT JOIN organizations o ON o.id=e.organization_id LEFT JOIN seat_assignments a ON a.employee_id=e.id AND a.ended_at IS NULL LEFT JOIN seats se ON se.id=a.seat_id WHERE ($1='' OR e.name ILIKE '%%'||$1||'%%' OR e.employee_no ILIKE '%%'||$1||'%%' OR e.email ILIKE '%%'||$1||'%%' OR o.name ILIKE '%%'||$1||'%%') AND ($2='' OR e.organization_id=$2) AND ($3='' OR e.status=$3) AND ($4='' OR ($4='assigned' AND a.seat_id IS NOT NULL) OR ($4='unassigned' AND a.seat_id IS NULL)) ORDER BY e.name LIMIT $5`, q, org, status, assignment, limit)
	if err != nil {
		notFoundOrServer(w, err)
		return
	}
	defer rows.Close()
	items, err := scanEmployees(rows)
	if err != nil {
		notFoundOrServer(w, err)
		return
	}
	writeJSON(w, 200, map[string]any{"items": items})
}

func scanEmployees(rows rowScanner) ([]Employee, error) {
	items := []Employee{}
	for rows.Next() {
		var item Employee
		if err := rows.Scan(&item.ID, &item.EmployeeNo, &item.Name, &item.Email, &item.OrganizationID, &item.OrganizationName, &item.Title, &item.Position, &item.Workplace, &item.Status, &item.SeatID, &item.SeatNo); err != nil {
			return nil, err
		}
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

